static int solve6(double A[6][7]){for(int c=0;c<6;c++){int p=c; for(int r=c+1;r<6;r++) if(fabs(A[r][c])>fabs(A[p][c]))p=r; if(fabs(A[p][c])<1e-9)return 0; if(p!=c)for(int k=c;k<7;k++){double t=A[c][k];A[c][k]=A[p][k];A[p][k]=t;} double d=A[c][c]; for(int k=c;k<7;k++)A[c][k]/=d; for(int r=0;r<6;r++)if(r!=c){double m=A[r][c]; for(int k=c;k<7;k++)A[r][k]-=m*A[c][k];}} return 1;}
