static int parse_ra(const char*s,float*out){int h=0,m=0;float sec=0;if(sscanf(s,":Sr%d:%d:%f#",&h,&m,&sec)==3){*out=h+m/60.0f+sec/3600.0f;return 1;}return 0;} static int parse_dec(const char*s,float*out){char sign='+';int d=0,m=0;float sec=0;if(sscanf(s,":Sd%c%d*%d:%f#",&sign,&d,&m,&sec)==4){*out=(float)d+m/60.0f+sec/3600.0f; if(sign=='-')*out=-*out; return 1;}return 0;}
